def parse():
    items=collections.defaultdict(lambda: collections.defaultdict(set))
    for f in sorted(glob.glob(S+'/txt/*.txt')):
        b=os.path.basename(f)[:-4]
        if b.startswith('LCI'): continue
        t=open(f).read(); L=t.split('\n')
